examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchText(text = {{title}}, style = MonarchTextStyle.Title)
    MonarchText(text = {{description}}, color = MonarchTheme.colors.textMuted)
    MonarchPeriodSelector(
        value = period,
        onValueChange = { period = it },
        today = {{today|millis}},
        locale = Locale.forLanguageTag({{locale}}),
    )
    MonarchButton(
        text = {{arrange}},
        onClick = { arranging = !arranging },
        variant = MonarchButtonVariant.Secondary,
        size = MonarchButtonSize.Sm,
    )
    FlowRow(
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
    ) {
        MonarchStatCard(label = {{kpis.0.label}}, value = {{kpis.0.value|double}})
        MonarchStatCard(
            label = {{kpis.1.label}},
            value = {{kpis.1.value|double}},
            format = MonarchMetricFormat.Currency({{kpis.1.currency}}),
            compact = {{kpis.1.compact}},
            locale = Locale.forLanguageTag({{locale}}),
        )
        MonarchStatCard(label = {{kpis.2.label}}, value = {{kpis.2.value|double}})
    }
    MonarchInsightStrip(
        insights = listOf(
            MonarchInsight(
                id = {{insight.id}},
                title = {{insight.title}},
                why = {{insight.why}},
                origin = MonarchInsightOrigin.{{insight.origin|pascal}},
                tone = {{insight.severity|tone}},
                actionLabel = {{insight.action}},
                onAction = {},
            ),
        ),
        title = {{headings.insights}},
        layout = MonarchInsightStripLayout.Stack,
    )
    MonarchDashboardGrid(
        items = sections,
        key = { it },
        itemLabel = { it },
        editing = arranging,
        modifier = Modifier.fillMaxSize(),
    ) { section ->
        when (section) {
            {{headings.composition}} -> Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
            MonarchText(text = section, style = MonarchTextStyle.Subheading)
            MonarchDonutChart(
                    title = {{composition.title}},
                    segments = listOf(
                        MonarchDonutChartSegment({{composition.segments.0.key}}, {{composition.segments.0.label}}, value = {{composition.segments.0.value|double}}),
                        MonarchDonutChartSegment({{composition.segments.1.key}}, {{composition.segments.1.label}}, value = {{composition.segments.1.value|double}}),
                        MonarchDonutChartSegment({{composition.segments.2.key}}, {{composition.segments.2.label}}, value = {{composition.segments.2.value|double}}),
                        MonarchDonutChartSegment({{composition.segments.3.key}}, {{composition.segments.3.label}}, value = {{composition.segments.3.value|double}}),
                    ),
                    centerValue = {{composition.centerValue}},
                    centerLabel = {{composition.centerLabel}},
                )
        }
            {{headings.attention}} -> MonarchWidget(title = section) {
                Row(modifier = Modifier.padding(vertical = MonarchTheme.spacing.space2), verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = {{attention.0.label}}, modifier = Modifier.weight(1f))
                    MonarchBadge(text = {{attention.0.badge}}, tone = {{attention.0.tone|tone}})
                }
                MonarchDivider(variant = MonarchDividerVariant.Subtle)
                Row(modifier = Modifier.padding(vertical = MonarchTheme.spacing.space2), verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = {{attention.1.label}}, modifier = Modifier.weight(1f))
                    MonarchBadge(text = {{attention.1.badge}}, tone = {{attention.1.tone|tone}})
                }
            }
            {{headings.upcoming}} -> MonarchWidget(title = section) {
                Row(modifier = Modifier.padding(vertical = MonarchTheme.spacing.space2)) {
                    MonarchText(text = {{upcoming.0.label}}, modifier = Modifier.weight(1f))
                    MonarchText(text = {{upcoming.0.value}})
                }
                MonarchDivider(variant = MonarchDividerVariant.Subtle)
                Row(modifier = Modifier.padding(vertical = MonarchTheme.spacing.space2)) {
                    MonarchText(text = {{upcoming.1.label}}, modifier = Modifier.weight(1f))
                    MonarchText(text = {{upcoming.1.value}})
                }
                MonarchDivider(variant = MonarchDividerVariant.Subtle)
                Row(modifier = Modifier.padding(vertical = MonarchTheme.spacing.space2)) {
                    MonarchText(text = {{upcoming.2.label}}, modifier = Modifier.weight(1f))
                    MonarchText(text = {{upcoming.2.value}})
                }
            }
            {{headings.breakdown}} -> MonarchWidget(title = section) {
                MonarchBarList(
                    items = listOf(
                        MonarchBarListItem({{breakdown.items.0.label}}, value = {{breakdown.items.0.value|double}}, id = {{breakdown.items.0.id}}),
                        MonarchBarListItem({{breakdown.items.1.label}}, value = {{breakdown.items.1.value|double}}, id = {{breakdown.items.1.id}}),
                        MonarchBarListItem({{breakdown.items.2.label}}, value = {{breakdown.items.2.value|double}}, id = {{breakdown.items.2.id}}),
                        MonarchBarListItem({{breakdown.items.3.label}}, value = {{breakdown.items.3.value|double}}, id = {{breakdown.items.3.id}}),
                    ),
                    label = {{breakdown.label}},
                )
            }
            {{headings.ranking}} -> MonarchWidget(title = section) {
                MonarchLeaderboard(
                    entries = listOf(
                        MonarchLeaderboardEntry({{ranking.entries.0.name}}, {{ranking.entries.0.value|double}}, id = {{ranking.entries.0.id}}, display = {{ranking.entries.0.display}}),
                        MonarchLeaderboardEntry({{ranking.entries.1.name}}, {{ranking.entries.1.value|double}}, id = {{ranking.entries.1.id}}, display = {{ranking.entries.1.display}}),
                        MonarchLeaderboardEntry({{ranking.entries.2.name}}, {{ranking.entries.2.value|double}}, id = {{ranking.entries.2.id}}, display = {{ranking.entries.2.display}}),
                    ),
                    valueLabel = {{ranking.valueLabel}},
                    showAvatars = false,
                )
            }
            else -> MonarchWidget(title = section) {
                MonarchActivityTimeline(
                    events = events,
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(max = 900.dp),
                    groupByDay = false,
                    density = MonarchActivityTimelineDensity.Compact,
                    now = now,
                    timeZone = "UTC",
                )
            }
        }
    }
}

examples.setupTemplate:
val now = {{now|millis}}
var period by remember { mutableStateOf(MonarchPeriodValue(MonarchPeriodPreset.Last7Days)) }
var arranging by remember { mutableStateOf(false) }
val sections = listOf({{headings.composition}}, {{headings.attention}}, {{headings.upcoming}}, {{headings.breakdown}}, {{headings.ranking}}, {{headings.activity}})
val events = listOf(
    MonarchActivityTimelineEvent(
        id = {{events.0.id}},
        verb = {{events.0.verb}},
        time = {{events.0.time|millis}},
        actor = MonarchActivityTimelineActor({{events.0.actor}}),
        target = {{events.0.object}},
    ),
    MonarchActivityTimelineEvent(
        id = {{events.1.id}},
        verb = {{events.1.verb}},
        time = {{events.1.time|millis}},
        actor = MonarchActivityTimelineActor({{events.1.actor}}),
        target = {{events.1.object}},
    ),
)

