                Row(modifier = Modifier.padding(vertical = MonarchTheme.spacing.space2)) {
                    MonarchText(text = "CRM licences", modifier = Modifier.weight(1f))
                    MonarchText(text = "14 Jul 2026")
                }
                MonarchDivider(variant = MonarchDividerVariant.Subtle)
                Row(modifier = Modifier.padding(vertical = MonarchTheme.spacing.space2)) {
                    MonarchText(text = "Cleaning services, Leeds", modifier = Modifier.weight(1f))
                    MonarchText(text = "31 Jul 2026")
